import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.CjCc0aQE.js";const w=JSON.parse(`{"title":"Live plays a mixed workout with the workout player's steps","description":"","frontmatter":{"status":"accepted","date":"2026-11-03T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0018-live-plays-mixed-workouts-with-the-players-steps.md","filePath":"docs/adr/0018-live-plays-mixed-workouts-with-the-players-steps.md"}`),r={name:"docs/adr/0018-live-plays-mixed-workouts-with-the-players-steps.md"};function i(l,e,n,h,d,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="live-plays-a-mixed-workout-with-the-workout-player-s-steps" tabindex="-1">Live plays a mixed workout with the workout player&#39;s steps <a class="header-anchor" href="#live-plays-a-mixed-workout-with-the-workout-player-s-steps" aria-label="Permalink to &quot;Live plays a mixed workout with the workout player&#39;s steps&quot;">​</a></h1><p>Live offers any saved workout with at least one walk or run, not only workouts made of walks and runs (<a href="./0013-workouts-have-a-format-not-a-type">ADR 0013</a> said the picker offered the latter). A <strong>mixed workout</strong> is played by the Live recording itself, drawn like the guided player: the same bar, work step and rest, full screen, with Live&#39;s numbers on top. We chose this over handing the workout to the guided player with a treadmill strip, because the recording, the belt rules and the finish questions already live in <code>LiveModel</code>, and a second owner of the session would have meant two models writing the same event log.</p><p>The step the screen shows comes from one shared piece, <code>PlayerFace</code>, which the guided <code>PlayerModel</code> also uses. Android and iOS share the step views too, so a mixed workout in Live and the same workout in the player cannot drift apart.</p><h2 id="what-the-treadmill-does-step-by-step" tabindex="-1">What the treadmill does, step by step <a class="header-anchor" href="#what-the-treadmill-does-step-by-step" aria-label="Permalink to &quot;What the treadmill does, step by step&quot;">​</a></h2><ul><li><strong>A walk or run follows the belt</strong> as in a pure treadmill workout: samples are recorded, a halted belt pauses the recording, a distance target ends when the treadmill reports it. A rest between two walks or runs follows it too.</li><li><strong>Any other exercise ignores the belt.</strong> No treadmill samples are recorded, a still belt or a lost treadmill neither pauses the recording nor starts the finish question, and the tiles shrink to what the phone is streamed, such as the heart rate.</li><li><strong>A walk or run reached from another exercise always waits to begin</strong>, as the person may still be on their way to the treadmill, or it may not be connected yet. Following the treadmill with the belt still, it starts when the belt moves, and &quot;Start without it&quot; is the way out. With the belt already moving, or with no treadmill, it shows Start and is timed by the phone. Skip and Done are always there: Done cuts a step short without the feel of skipping it. A workout that opens with a walk or run keeps waiting for the belt in the picker, as Start always did; one that opens with another exercise starts at once.</li><li><strong>History</strong> keeps one session. Its treadmill totals come from the samples, so from the walks and runs only.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The wait is a pause the app makes at the step boundary, so the step&#39;s clock starts when it begins, and the session clock does not count the wait.</li><li>The console&#39;s distance counter may be reset between two walks. <code>TreadmillRecorder.restart()</code> makes a distance target count from the next reading, but the summary still reads a session&#39;s distance as the counter&#39;s growth from its first reading to its last, so a reset in between skews it (marked <code>// CLEANUP:</code> in the code).</li></ul>',7)])])}const u=t(r,[["render",i]]);export{w as __pageData,u as default};
